// per-domain cert served by SNI. These tables are additive — they do NOT touch
// the Server-scoped control panel (Website / VpsDatabase / AppInstall).
// ============================================================================

enum HostingNodeStatus {
  ONLINE
  DEGRADED
  OFFLINE
}

/// A shared-hosting box we SSH into to provision customer accounts. Distinct from
/// the Proxmox `Node` (which manages VMs) — this one runs nginx + PHP-FPM + a DB
/// server + mail, and its `publicIp` is the shared A-record target for every
/// account on it.
model HostingNode {
  id              String            @id @default(cuid())
  name            String            @unique
  publicIp        String // the shared IP every account's domains point at
  sshHost         String // host/IP we SSH to (may differ from publicIp on NAT)
  sshPort         Int               @default(22)
  // Root credentials to provision on the box. Encrypted at rest, like server
  // root passwords. Exactly one of these is used.
  rootPasswordEnc String?
  hostnameFqdn    String? // e.g. srv12.nxeon.cloud — a CNAME target / cert SAN
  // Capacity for the account scheduler (least-loaded placement).
  maxAccounts     Int               @default(200)
  diskTotalGB     Int               @default(500)
  enabled         Boolean           @default(true)
  status          HostingNodeStatus @default(ONLINE)
  lastSeenAt      DateTime?
  // Node hardening (runs onboard-hosting-node.sh over the platform's own SSH):
  // NONE | QUEUED | RUNNING | DONE | FAILED. Admin-triggered; the worker sweep
  // picks up QUEUED nodes, streams the script, and records the tail + timestamp.
  hardenStatus    String            @default("NONE")
  hardenedAt      DateTime?
  hardenLog       String?
  createdAt       DateTime          @default(now())
  accounts        HostingAccount[]
  // Live telemetry: this node runs ONE centralized nxeon-shipper (not one per
  // customer account) tailing the shared nginx access logs for every vhost on
  // the box. Same hash-only-at-rest convention as Server.telemetryTokenHash.
  telemetryTokenHash   String?         @unique
  // Deploy state machine for that centralized shipper — identical shape to
  // hardenStatus/hardenedAt/hardenLog above (worker hostingNodeTelemetryDeploySweep
  // picks up QUEUED nodes). Admin-triggered only; never auto-queued, so adding
  // this feature never touches a node that's already live until someone asks it to.
  telemetryDeployStatus String          @default("NONE")
  telemetryDeployedAt   DateTime?
  telemetryDeployLog    String?
}

/// A shared-hosting product tier (Starter / Plus / Pro web hosting), priced well
/// below a VPS and sold by resource limits rather than a VM size.
model HostingPlan {
  id            String           @id @default(cuid())
  slug          String           @unique
  name          String
  priceCents    Int
  diskGB        Int              @default(10)
  maxSites      Int              @default(1) // addon domains this account may host
  maxDatabases  Int              @default(1)
  bandwidthTB   Float            @default(1)
  // Bundled email mailboxes included with the plan. -1 = unlimited. Provisioned
  // on our own Nxeon Mail (Mailcow) backend when the account is created.
  mailboxes     Int              @default(1)
  // Marketing flags surfaced on the plan cards.
  freeMigration Boolean          @default(false) // "we move your existing site free"
  featured      Boolean          @default(false) // "Most popular" highlight
  tagline       String           @default("") // one-line pitch under the plan name
  phpVersions   String           @default("8.3") // comma-separated allowed PHP versions
  active        Boolean          @default(true)
  sortOrder     Int              @default(0)
  createdAt     DateTime         @default(now())
  accounts      HostingAccount[]
}

enum HostingAccountStatus {
  PENDING // created, waiting for the provisioner
  PROVISIONING
  ACTIVE
  SUSPENDED
  FAILED
  DELETING
}

/// One customer's isolated shared-hosting account on a HostingNode: a jailed
/// Linux user with its own PHP-FPM pool, disk quota, primary domain and (later)
/// additional sites / databases / mailboxes. The unit of isolation and billing.
model HostingAccount {
  id                String                 @id @default(cuid())
  userId            String
  user              User                   @relation(fields: [userId], references: [id], onDelete: Cascade)
  // Set when this order arrived via a partner deep link (?ref=kodely on
  // /dashboard/deploy?product=hosting, captured by PartnerSourceCapture). Null for
  // every direct Nxeon order. Gates the webhook notify in worker/hosting.ts.
  partnerSource     String?
  hostingNodeId     String
  node              HostingNode            @relation(fields: [hostingNodeId], references: [id])
  planId            String
  plan              HostingPlan            @relation(fields: [planId], references: [id])
  // The jailed system username on the box (derived, unique per node). All the
  // account's files live under /home/<username>; its FPM pool runs AS this user.
  username          String
  primaryDomain     String // the account's main domain (name-based vhost server_name)
  status            HostingAccountStatus   @default(PENDING)
  // Effective quota snapshot (copied from the plan at creation so a plan edit
  // doesn't silently re-quota live accounts). ALWAYS already includes any purchased
  // `extraDiskGB` — it is (plan.diskGB + extraDiskGB) × 1024 — so the node's setquota
  // (taskApplyPlanLimits) never has to know about the add-on.
  diskQuotaMB       Int
  /// Purchased extra storage in GB, on TOP of the plan allowance (upsell). Add-only,
  /// mirroring Server.extraDiskGB — a live filesystem quota is only ever raised, never
  /// shrunk. Priced per-GB/month via `extra_disk_gb_price_cents` (the SAME rate VPS
  /// extra disk uses) and billed every renewal alongside the plan.
  extraDiskGB       Int                    @default(0)
  maxSites          Int
  maxDatabases      Int
  /// Billing term this account was SOLD on, in months: 1 = monthly, 12 = annual.
  /// The renewal sweep (worker/product-renewals.ts) charges
  /// `termPriceCents(plan.priceCents, termMonths, annualDiscountPct)` and pushes
  /// `expiresAt` forward this many months, so an annual account renews annually at
  /// the rate it was sold — displayed === charged === renewed. Defaults to 1 so
  /// every pre-existing row keeps billing monthly exactly as before.
  termMonths        Int                    @default(1)
  /// PERCENT the ANNUAL discount was set to when THIS account's term was sold — a
  /// snapshot of `annual_discount_percent` frozen at sale, exactly like
  /// Server.annualDiscountPct. The renewal reads THIS (falling back to the live
  /// setting when null) so an annual account renews at the sold rate even if the
  /// admin retunes the discount afterwards. NULL on monthly accounts and on rows
  /// that predate this column — the live setting is used for those, which for a
  /// monthly term changes nothing.
  annualDiscountPct Float?
  // PHP version the account's FPM pool runs (within the plan's allowed set).
  phpVersion        String                 @default("8.3")
  // HTTPS: set once a per-domain Let's Encrypt cert is issued (SNI on the shared
  // IP). The SSL sweep flips this after the domain resolves to us.
  sslActive         Boolean                @default(false)
  // Live disk/inode usage, refreshed by hostingUsageSweep (null until first
  // measured). Powers the real usage meters in the customer panel.
  diskUsedMB        Int?
  inodesUsed        Int?
  usageAt           DateTime?
  // Serve-verification health, refreshed by hostingHealthSweep (null until first
  // checked). serveHttpOk/serveHttpsOk record whether nginx actually answers on
  // 80/443 for this domain from the node — the guardrail against a customer ever
  // seeing ERR_CONNECTION_REFUSED while the panel claims "active". healthNote is a
  // short human string for the DNS→HTTPS stepper; healthCheckedAt timestamps it.
  // recheckRequested is set by the customer "Check now / Go live" button so the
  // sweep picks that account up before its normal cadence, then clears it.
  serveHttpOk       Boolean?
  serveHttpsOk      Boolean?
  healthNote        String?
  healthCheckedAt   DateTime?
  recheckRequested  Boolean                @default(false)
  // The account's SFTP/login password, encrypted; set at provision and shown to
  // the customer ONCE, then cleared. (SFTP is a reviewed later phase.)
  sftpPasswordEnc   String?
  // The per-account, hard-to-guess URL path where the Adminer DB manager is
  // dropped inside this account's own webroot (e.g. /nxtools-<random>/adminer.php),
  // served by this account's own PHP-FPM socket. Null until the customer installs
  // it from the Databases tab. A leaked path yields no cross-tenant access: the
  // customer must still log in with their OWN scoped DB user (localhost, granted on
  // their databases only). See INSTALL_DBTOOL in worker/hosting.ts.
  dbToolPath        String?
  // Proprietary in-portal DB manager (Nxeon-built, replaces Adminer). A single
  // account-level MySQL user granted on `<username>\_%`.* ONLY — i.e. every one of
  // this account's databases and NOTHING else (db-scoped grant, so no global
  // FILE/PROCESS/SUPER either). Its password is encrypted AT REST (persistent,
  // like sftpPasswordEnc) because the manager re-authenticates as this user on
  // every query, server-side — the credential is NEVER sent to the browser. The
  // ENSURE_DBMGR task creates the user on the node; dbMgrReady flips true when it
  // succeeds. See lib/hosting-db.ts + lib/actions-hosting-db.ts.
  dbMgrUser         String?
  dbMgrPassEnc      String?
  dbMgrReady        Boolean                @default(false)
  // Provisioning bookkeeping.
  error             String?
  // Best-effort, human-readable label for whichever real provisioning step is
  // running right now (e.g. "Creating your account…", "Configuring your web
  // server…") — written by worker/hosting.ts's provisionHostingAccount() /
  // applyIsolation() between real, observable command groups. Read (alongside a
  // live HostingTask, e.g. a queued WordPress install) by
  // lib/provisioning-step.ts and shown by <ProvisioningOverlay/>. Null = no real
  // signal yet (falls back to a generic message) or not mid-provision.
  provisioningStep  String?
  provisionedAt     DateTime?
  expiresAt         DateTime?
  suspendedNote     String?
  createdAt         DateTime               @default(now())
  updatedAt         DateTime               @updatedAt
  databases         HostingDatabase[]
  tasks             HostingTask[]
  backups           HostingBackup[]
  subdomains        HostingSubdomain[]
  addonDomains      HostingAddonDomain[]
  crons             HostingCron[]
  hostnameClaims    HostingHostnameClaim[]

  @@unique([hostingNodeId, username])
  @@index([userId])
  @@index([status])
}

/// Which kind of resource a hostname claim reserves. Purely descriptive — the
/// authoritative guarantee is the UNIQUE(hostname) on the claim row itself.
enum HostingClaimKind {
  PRIMARY
  SUBDOMAIN
  ADDON
}

/// Single authoritative registry of every hostname served on the fleet, spanning
/// ALL THREE places a name can live — an account's primary domain, a subdomain,
/// or an addon domain. The UNIQUE(hostname) is the atomic cross-tenant guard: a
/// claim row is inserted in the SAME transaction as the resource row it names, so
/// two concurrent requests that both pass the advisory isHostnameClaimed()
/// pre-check can never both commit the same nginx `server_name` — the second
/// INSERT fails on the unique (Prisma P2002) and rolls its whole transaction back.
/// Before this table there was no single constraint spanning the three hostname
/// tables (primaryDomain has no unique), so co-tenants on one node could shadow
/// each other's vhost (security audit: co-tenant vhost-shadowing TOCTOU). The
/// hostname is stored normalized (trimmed + lowercased) so case/format variants
/// can't dodge the unique. Freed by deleting the row when the resource is removed
/// (same tx as the delete / on account termination); the accountId relation also
/// cascades if the account row is ever hard-deleted.
model HostingHostnameClaim {
  id        String           @id @default(cuid())
  hostname  String           @unique
  accountId String
  account   HostingAccount   @relation(fields: [accountId], references: [id], onDelete: Cascade)
  kind      HostingClaimKind
  createdAt DateTime         @default(now())

  @@index([accountId])
}

enum HostingTaskKind {
  PHP_SWITCH
  WORDPRESS_INSTALL
  APP_INSTALL
  BACKUP
  RESTORE
  // Account lifecycle — enacted by the provisioner (inert until ENABLE_SHARED_HOSTING).
  SUSPEND // disable vhost + FPM pool + lock the unix user (reversible)
  UNSUSPEND // reverse a SUSPEND
  TERMINATE // remove vhost/FPM, delete the jailed user + home, drop scoped DBs
  // cPanel-class site management — each queues one node operation (inert until enabled).
  CREATE_SUBDOMAIN // mkdir a docroot + write/enable a <label>.<primary> vhost
  DELETE_SUBDOMAIN // reverse: remove the vhost + docroot
  CREATE_ADDON_DOMAIN // full external domain: own docroot + vhost
  DELETE_ADDON_DOMAIN // reverse: remove the vhost + docroot
  CREATE_CRON // (re)write the jailed user's crontab from its ACTIVE cron rows
  DELETE_CRON // remove a cron row + rewrite the crontab
  // Drop the Adminer DB manager into the account webroot (served by the account's
  // own FPM socket; login is the customer's scoped DB user — no root, no auto-login).
  INSTALL_DBTOOL
  // Create/repair the account-level scoped MySQL user for the proprietary in-portal
  // DB manager (granted on `<username>\_%`.* only). Idempotent. See taskEnsureDbMgr.
  ENSURE_DBMGR
  // Re-apply the account's snapshotted plan limits on the node after a plan upgrade
  // (raise the disk quota via setquota; rewrite the FPM pool). Idempotent.
  APPLY_PLAN_LIMITS
  // Change a scoped MySQL user's password on the node (customer-initiated DB
  // password reset). Runs ALTER USER … IDENTIFIED BY. Idempotent. See taskResetDbPassword.
  RESET_DB_PASSWORD
  // Promote a real domain (an existing ACTIVE addon domain) to the account's
  // primaryDomain: regenerate the primary vhost hosting-<user>.conf with the new
  // domain as server_name, KEEP the old primary hostname as an alias server_name
  // (so the old address keeps working), run `wp search-replace`+`option update`
  // when WordPress is detected in the primary docroot, then flip DB primaryDomain
  // and re-key the hostname claims. Worst-case safe: on any failure the old
  // address keeps serving and primaryDomain is left unchanged. See taskSetPrimaryDomain.
  SET_PRIMARY_DOMAIN
}

enum HostingTaskStatus {
  PENDING
  RUNNING
  DONE
  FAILED
}

/// A queued panel operation on an account, run by the worker over the node SSH
/// (PHP switch, one-click app install, backup, restore). `payload`/`result` hold
/// small JSON; any secret in a result (e.g. a WordPress admin password) is
/// shown ONCE then cleared.
model HostingTask {
  id        String            @id @default(cuid())
  accountId String
  account   HostingAccount    @relation(fields: [accountId], references: [id], onDelete: Cascade)
  kind      HostingTaskKind
  status    HostingTaskStatus @default(PENDING)
  payload   String? // JSON in
  result    String? // JSON out (may hold a one-time secret until read)
  error     String?
  createdAt DateTime          @default(now())
  updatedAt DateTime          @updatedAt

  @@index([status])
  @@index([accountId])
}

/// A stored backup of an account (home archive + DB dumps) on its node.
model HostingBackup {
  id        String         @id @default(cuid())
  accountId String
  account   HostingAccount @relation(fields: [accountId], references: [id], onDelete: Cascade)
  path      String // absolute path of the archive on the node
  sizeBytes Int            @default(0)
  createdAt DateTime       @default(now())

  @@index([accountId])
}

enum HostingDatabaseStatus {
  PENDING
  ACTIVE
  FAILED
  DELETING
}

/// A MySQL/MariaDB database + its scoped owner user for a hosting account. The
/// generated password is shown ONCE at creation; `passwordEnc` holds it only
/// transiently so the provisioner can apply it, then it is cleared. The DB user
/// is granted rights on THIS database only — the shared-box isolation boundary
/// for data.
model HostingDatabase {
  id          String                @id @default(cuid())
  accountId   String
  account     HostingAccount        @relation(fields: [accountId], references: [id], onDelete: Cascade)
  name        String // real DB name on the box, prefixed by the account username
  dbUser      String
  passwordEnc String? // encrypted; CLEARED once the create step applies it
  status      HostingDatabaseStatus @default(PENDING)
  error       String?
  createdAt   DateTime              @default(now())

  @@unique([accountId, name])
  @@index([accountId])
}

/// Shared lifecycle state for the cPanel-class site resources (subdomains, addon
/// domains, cron jobs). Mirrors HostingDatabaseStatus but kept separate so those
/// resources can evolve independently. The provisioner flips PENDING → ACTIVE and
/// removes rows on DELETING (inert until ENABLE_SHARED_HOSTING).
enum HostingResourceStatus {
  PENDING
  ACTIVE
  FAILED
  DELETING
}

/// A subdomain of an account's primary domain (e.g. shop.example.com) with its
/// own docroot + name-based vhost. Counts against the plan's maxSites budget
/// together with addon domains.
model HostingSubdomain {
  id        String                @id @default(cuid())
  accountId String
  account   HostingAccount        @relation(fields: [accountId], references: [id], onDelete: Cascade)
  label     String // the leftmost label, e.g. "shop"
  fqdn      String                @unique // shop.example.com
  docroot   String // /home/<user>/subdomains/<label>/public_html
  sslActive Boolean               @default(false)
  status    HostingResourceStatus @default(PENDING)
  createdAt DateTime              @default(now())

  @@index([accountId])
}

/// A full external domain hosted on the account (its own docroot + vhost).
/// Cross-tenant unique like the primary domain — no two accounts may host the
/// same name. Counts against maxSites together with subdomains.
model HostingAddonDomain {
  id        String                @id @default(cuid())
  accountId String
  account   HostingAccount        @relation(fields: [accountId], references: [id], onDelete: Cascade)
  domain    String                @unique
  docroot   String // /home/<user>/domains/<domain>/public_html
  sslActive Boolean               @default(false)
  status    HostingResourceStatus @default(PENDING)
  createdAt DateTime              @default(now())

  @@index([accountId])
}

/// A cron job scheduled in the account's jailed-user crontab. The command runs
/// AS the jailed user, so it is confined to the account's own environment.
model HostingCron {
  id        String                @id @default(cuid())
  accountId String
  account   HostingAccount        @relation(fields: [accountId], references: [id], onDelete: Cascade)
  schedule  String // 5-field cron expression
  command   String
  status    HostingResourceStatus @default(PENDING)
  createdAt DateTime              @default(now())

  @@index([accountId])
}

// ============================================================================
// PROJECT BOARD (internal kanban for managing Nxeon)
// ----------------------------------------------------------------------------
// A Trello-style board: Board → columns (stages) → cards (ideas/features/bugs),
// with attachments (screenshots, files, videos) stored on this server's disk so
// they can be read + acted on directly, and comments. Admin-only.
// ============================================================================

enum CardType {
  IDEA
  FEATURE
  BUG
  CHORE
}

enum CardPriority {
  LOW
  NORMAL
  HIGH
  URGENT
}

enum AttachmentKind {
  IMAGE
  VIDEO
  FILE
}

// A product/app the boards belong to (e.g. Nxeon, Soul Pilates, studionexis).
// Boards are grouped under an App so the board page can be filtered per product.
model App {
  id        String   @id @default(cuid())
  name      String
  slug      String   @unique
  color     String?
  serverId  String?
  server    Server?  @relation(fields: [serverId], references: [id], onDelete: SetNull)
  // ---- Working context (2026-08-04) --------------------------------------
  // Where this app's code lives and how to build/deploy it, so a future Claude
  // session (or a human) can act on the RIGHT app without rediscovering the
  // layout each time. All nullable/additive (safe `db push`).
  //   codePath — absolute path to the checkout on its box (e.g. /opt/nxeon)
  //   repoUrl  — git remote, when the app has one (null for image-only apps)
  //   context  — free-form markdown: stack, build/deploy steps, conventions,
  //              gotchas. Edited by humans/Claude via the board's App settings.
  codePath  String?
  repoUrl   String?

import { notFound } from "next/navigation";
import { getHostingAccount } from "@/lib/actions-hosting";
import { db } from "@/lib/db";
import { decryptSecret } from "@/lib/crypto-box";
import { hostingProvisioningStep } from "@/lib/provisioning-step";
import { StatusDot, Badge } from "@/components/ui/primitives";
import { AutoRefresh } from "@/components/AutoRefresh";
import { ProvisioningOverlay } from "@/components/customer/ProvisioningOverlay";
import { HostingTabs } from "@/components/customer/hosting/HostingTabs";

export const dynamic = "force-dynamic";

export default async function HostingAccountPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ tab?: string; path?: string; purchase?: string }>;
}) {
  const [{ id }, { tab, path, purchase }] = await Promise.all([params, searchParams]);

  // getHostingAccount enforces owner-or-admin (throws) and returns null if missing.
  let account: Awaited<ReturnType<typeof getHostingAccount>> = null;
  try {
    account = await getHostingAccount(id);
  } catch {
    notFound();
  }
  if (!account) notFound();

  const transitional = account.status === "PENDING" || account.status === "PROVISIONING";

  // Ownership/admin access was already established by getHostingAccount above —
  // this second, narrower lookup just pulls the extra raw fields the overlay
  // needs (the encrypted SFTP credential, the node's address) that the public
  // HostingAccountView doesn't carry. Real progress label: see
  // lib/provisioning-step.ts — while PENDING/PROVISIONING it's the worker's own
  // per-command-group label; once ACTIVE it's whichever content task (most
  // commonly a WordPress install queued at order time) is still running.
  const [raw, stepLabel] = await Promise.all([
    db.hostingAccount.findUnique({
      where: { id: account.id },
      select: { sftpPasswordEnc: true, node: { select: { publicIp: true, hostnameFqdn: true } } },
    }),
    hostingProvisioningStep(account.id),
  ]);
  const sftpPassword = raw?.sftpPasswordEnc ? decryptSecret(raw.sftpPasswordEnc) : null;
  const sftpHost = raw?.node?.hostnameFqdn || raw?.node?.publicIp || null;
  // True while a real follow-on step (e.g. that WordPress install) is still
  // running even though the account itself already flipped ACTIVE — see
  // ProvisioningOverlay's `liveStepActive` prop doc for why this is safe against
  // hijacking the screen for a later, casual install.
  const installStepActive = account.status === "ACTIVE" && stepLabel !== null;

  const overlay = (
    <ProvisioningOverlay
      serverId={account.id}
      status={account.status}
      transitional={transitional}
      justPaid={purchase === "1"}
      provisionError={account.error}
      productLabel="hosting account"
      hostname={account.primaryDomain}
      // Shared Hosting has no VPS-style "connect" address — the closest analogue
      // is the SFTP login, so that's what's shown here; the live site URL is a
      // separate `extraInfo` row below rather than overloading this field.
      connectAddress={sftpHost ? `sftp://${account.username}@${sftpHost}` : null}
      planName={account.planName}
      osName={null}
      rootPassword={sftpPassword}
      rootPasswordLabel="SFTP password"
      extraInfo={[
        { label: "SFTP username", value: account.username },
        { label: "Website", value: `https://${account.primaryDomain}/`, href: `https://${account.primaryDomain}/` },
      ]}
      readyStatus="ACTIVE"
      liveStep={stepLabel}
      liveStepActive={installStepActive}
      dashboardHref={`/dashboard/hosting/${account.id}`}
    />
  );

  return (
    <div>
      {overlay}
      {(transitional || installStepActive) && <AutoRefresh />}

      <div className="mb-6">
        <div className="flex flex-wrap items-center gap-3">
          <h1 className="page-title">{account.primaryDomain}</h1>
          <StatusDot status={account.status} />
          {account.sslActive && <Badge tone="green">HTTPS</Badge>}
        </div>
        <div className="mt-2 flex flex-wrap items-center gap-2">
          <Badge tone="slate">{account.planName}</Badge>
          <Badge tone="slate">PHP {account.phpVersion}</Badge>
          <a href="/dashboard/hosting" className="text-xs text-slate-500 hover:text-slate-300 hover:underline">← All hosting</a>
        </div>
      </div>

      {transitional && (
        <div className="card mb-6 border-amber-500/30 text-sm text-amber-300">
          Your account is being set up — this usually takes under a minute. This page refreshes automatically.
        </div>
      )}

      <HostingTabs account={account} initialTab={tab} initialPath={path} />
    </div>
  );
}
