        </dl>
        {active ? (
          <div className="mt-4 border-t border-white/[0.06] pt-4">
            <PlanUpgrade accountId={account.id} />
          </div>
        ) : (
          <p className="mt-3 text-xs text-slate-500">Upgrades are available once the account is active.</p>
        )}
      </div>

      <div className="card border-red-500/20">
        <h3 className="mb-1 font-semibold text-red-300">Danger zone</h3>
        <p className="text-sm text-slate-400">
          Cancelling this hosting account permanently removes its files, databases and sites. This can’t be undone.
        </p>
        <div className="mt-4">
          <CancelHostingAccount accountId={account.id} primaryDomain={account.primaryDomain} />
        </div>
      </div>
    </div>
  );
}

/**
 * Self-serve hosting cancel. Destructive + irreversible, so it demands a strong
 * two-step confirmation: the customer must type the account's primary domain
 * exactly before the final "Cancel account" button unlocks. On success the account
 * flips to DELETING and the provisioner tears it down; we send the customer back to
 * the hosting list.
 */
function CancelHostingAccount({ accountId, primaryDomain }: { accountId: string; primaryDomain: string }) {
  const [open, setOpen] = useState(false);
  const [confirmText, setConfirmText] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const matches = confirmText.trim().toLowerCase() === primaryDomain.trim().toLowerCase();

  function close() {
    if (busy) return;
    setOpen(false);
    setConfirmText("");
    setError(null);
  }

  async function submit() {
    if (!matches || busy) return;
    setBusy(true);
    setError(null);
    const res = await cancelHostingAccount(accountId);
    if (res.error) {
      setError(res.error);
      setBusy(false);
      return;
    }
    // Account is now DELETING — leave this page for the hosting list.
    window.location.href = "/dashboard/hosting";
  }

  return (
    <>
      <button type="button" className="btn-secondary border-red-500/40 px-3 py-1.5 text-sm text-red-300 hover:bg-red-500/10" onClick={() => setOpen(true)}>
        Cancel hosting account
      </button>

      {open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm" onClick={close}>
          <div className="w-full max-w-md rounded-2xl border border-red-500/30 bg-navy-900 p-6 shadow-2xl" onClick={(e) => e.stopPropagation()}>
            <h3 className="font-semibold text-red-300">Cancel hosting account</h3>
            <p className="mt-2 text-sm text-slate-400">
              This permanently removes <span className="font-mono text-slate-200">{primaryDomain}</span> — its files,
              databases and sites. <span className="text-red-300">This can’t be undone and there is no backup afterwards.</span>
            </p>
            <label className="mt-4 block text-xs text-slate-400">
              Type <span className="font-mono text-slate-200">{primaryDomain}</span> to confirm
            </label>
            <input
              type="text"
              autoFocus
              value={confirmText}
              onChange={(e) => setConfirmText(e.target.value)}
              placeholder={primaryDomain}
              disabled={busy}
              className="mt-1.5 w-full rounded-lg border border-white/10 bg-white/[0.03] px-3 py-2 font-mono text-sm text-slate-100 outline-none focus:border-red-500/50"

