/** Shell-escape the raw SQL from buildScopedGrantSql for embedding in a
 *  double-quoted `mysql -e "..."`. Identifiers/passwords are already validated
 *  to safe charsets; only the SQL's own backticks need escaping so the shell
 *  doesn't treat them as command substitution. */
function sqlForMysqlExec(sql: string): string {
  return sql.replace(/`/g, "\\`");
}

