/**
 * DNS→HTTPS stepper driven by the REAL serve-verification the worker records
 * (serveHttpOk / serveHttpsOk / sslActive), so it can never claim "live" while
 * HTTPS actually refuses. Three overall states, per the account's measured health:
 *   • verified — a trusted cert is live (sslActive) and 443 answers → "HTTPS live ✓"
 *   • issuing  — the site answers (self-signed 443 or HTTP) but no trusted cert yet
 *   • dns      — nothing answers for the domain yet (DNS not pointed at us)
 */
function DnsStepper({ account }: { account: HostingAccountView }) {
  const checked = account.healthCheckedAt != null || account.serveHttpOk != null;
  const serving = account.serveHttpOk === true || account.serveHttpsOk === true;
  const verified = account.sslActive && account.serveHttpsOk !== false;
  const state: "verified" | "issuing" | "dns" | "pending" =
    verified ? "verified" : serving ? "issuing" : checked ? "dns" : "pending";

  const free = account.isFreeSubdomain;
  const steps = [
    { label: free ? "DNS ready" : "Point domain", done: true, hint: free ? "Set up automatically" : "Add the A record above" },
    {
      label: "Site live",
      done: state === "issuing" || state === "verified",
      hint: state === "issuing" || state === "verified" ? "Serving traffic" : state === "dns" ? "DNS not detected yet" : "Checking…",
    },
    {
      label: "HTTPS verified",
      done: state === "verified",
      hint: state === "verified" ? "Certificate trusted" : state === "issuing" ? "Issuing certificate" : "Auto after DNS",
    },
  ];

  const headline =
    account.healthNote ??
    (state === "verified" ? "HTTPS live — verified" : state === "issuing" ? "HTTP live, HTTPS issuing" : state === "dns" ? "DNS not detected yet" : "Not checked yet");
  const headlineTone = state === "verified" ? "text-emerald-300" : state === "dns" ? "text-slate-400" : "text-amber-300";

  return (
    <div className="mt-4">
      <div className="flex items-center">
        {steps.map((s, i) => (
          <div key={s.label} className="flex flex-1 items-center last:flex-none">
            <div className="flex flex-col items-center">
              <span className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] ${s.done ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300" : "border-amber-500/40 bg-amber-500/10 text-amber-300"}`}>
                {s.done ? "✓" : i + 1}
              </span>
            </div>
            {i < steps.length - 1 && <div className={`mx-2 h-px flex-1 ${steps[i + 1].done ? "bg-emerald-500/40" : "bg-white/10"}`} />}
          </div>
        ))}
      </div>
      <div className="mt-1.5 flex items-start justify-between text-[11px]">
        {steps.map((s) => (
          <div key={s.label} className="flex-1 text-center first:text-left last:text-right">
            <p className={s.done ? "text-emerald-300" : "text-slate-400"}>{s.label}</p>
            <p className="text-slate-500">{s.hint}</p>
          </div>
        ))}
      </div>
      <p className={`mt-3 text-xs font-medium ${headlineTone}`}>
        {headline}
        {account.healthCheckedAt && (
          <span className="ml-1 font-normal text-slate-500">· checked {new Date(account.healthCheckedAt).toLocaleTimeString()}</span>
        )}
      </p>
      {state !== "verified" && (
        <p className="mt-1 text-xs text-slate-500">
          {free ? (
            <>A trusted HTTPS certificate is issued automatically once provisioning completes — this usually takes a minute. Use <span className="text-slate-300">Refresh</span> to check right away.</>
          ) : (
            <>A trusted HTTPS certificate is issued automatically once your domain resolves to us — this can take a few minutes after you set the DNS record. Use <span className="text-slate-300">Go live</span> to check right away.</>
          )}
        </p>
      )}
    </div>

import { NextRequest, NextResponse } from "next/server";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { fsReadBuffer, fsWriteBuffer, fsStatSize, fsTargetFor } from "@/lib/hosting-fs";
import { SANDBOX } from "@/lib/sandbox";

const MAX_UPLOAD = 100 * 1024 * 1024;
// Downloads buffer the whole file in memory (Buffer.concat), so cap the size we're
// willing to read to keep one tenant's giant file from OOMing the panel (MEDIUM-3).
const MAX_DOWNLOAD = 100 * 1024 * 1024;

async function ownedNode(accountId: string) {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { node: true } });
  if (!a) return null;
  if (a.userId !== user.id && user.role !== "ADMIN") return null;
  if (a.status !== "ACTIVE") return null;
  return a;
}

/** Upload a file into the account webroot (jailed). ?accountId=&path= */
export async function POST(req: NextRequest) {
  const a = await ownedNode(req.nextUrl.searchParams.get("accountId") ?? "");
  if (!a) return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  const dir = req.nextUrl.searchParams.get("path") ?? "public_html";
  const form = await req.formData();
  const file = form.get("file");
  if (!(file instanceof File)) return NextResponse.json({ error: "No file" }, { status: 400 });
  if (file.size > MAX_UPLOAD) return NextResponse.json({ error: "File too large (max 100 MB)" }, { status: 413 });
  const safeName = file.name.replace(/[^A-Za-z0-9._-]/g, "_").slice(0, 120);
  if (SANDBOX) return NextResponse.json({ ok: true });
  const t = fsTargetFor(a);
  if (!t) return NextResponse.json({ error: "File manager not ready" }, { status: 409 });
  try {
    await fsWriteBuffer(t, `${dir}/${safeName}`, Buffer.from(await file.arrayBuffer()));
    return NextResponse.json({ ok: true, name: safeName });
  } catch {
    return NextResponse.json({ error: "Upload failed" }, { status: 500 });
  }
}

/** Download a file from the account (jailed). ?accountId=&path= */
export async function GET(req: NextRequest) {
  const a = await ownedNode(req.nextUrl.searchParams.get("accountId") ?? "");
  if (!a) return new NextResponse("Forbidden", { status: 403 });
  const path = req.nextUrl.searchParams.get("path") ?? "";
  if (SANDBOX) return new NextResponse("sandbox", { status: 200 });
  const t = fsTargetFor(a);
  if (!t) return new NextResponse("Not ready", { status: 409 });
  try {
    // Stat first and refuse anything over the cap, so we never Buffer.concat a
    // huge file into memory (OOM DoS, MEDIUM-3).
    const size = await fsStatSize(t, path);
    if (size > MAX_DOWNLOAD) return new NextResponse("File too large to download (max 100 MB)", { status: 413 });
    const buf = await fsReadBuffer(t, path);
    const name = path.split("/").pop() ?? "download";
    return new NextResponse(new Uint8Array(buf), { status: 200, headers: { "Content-Type": "application/octet-stream", "Content-Disposition": `attachment; filename="${name.replace(/"/g, "")}"` } });
  } catch {
    return new NextResponse("Not found", { status: 404 });
  }
}
