/** Decrypt + return the account's SFTP password (owner or admin). cPanel-style. */
export async function revealHostingSftpPassword(accountId: string): Promise<{ password?: string; error?: string }> {
  const user = await requireUser();
  // An impersonating admin must not exfiltrate a customer's live SFTP credential
  // (matches orderHostingAccount/createHostingDatabase — audit LOW-1).
  await assertNotImpersonating();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true, sftpPasswordEnc: true } });
  if (!a) return { error: "Not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  const pw = a.sftpPasswordEnc ? decryptSecret(a.sftpPasswordEnc) : null;
  if (!pw) return { error: "No password on record yet — the account is still being set up." };
  return { password: pw };
}

