/**
 * Customer "Check now / Go live" — flag an ACTIVE account for an immediate
 * serve-verification + SSL recheck. The worker's fast lane (~30s) picks up
 * recheckRequested accounts before their routine 10-min cadence, verifies HTTP/
 * HTTPS from the node, self-heals a stale cert vhost, and nudges the SSL sweep so a
 * trusted certificate can start issuing. Owner or admin; a no-op for non-active
 * accounts (nothing to verify until it's provisioned).
 */
export async function recheckHostingHealth(id: string): Promise<HostingResult> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id }, select: { userId: true, status: true } });
  if (!a) return { error: "Not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
  await db.hostingAccount.update({ where: { id }, data: { recheckRequested: true } });
  revalidatePath(`/dashboard/hosting/${id}`);
  return { ok: true };
}

/** Re-queue a FAILED account for the provisioner. Owner or admin. */
export async function retryHostingProvision(id: string): Promise<HostingResult> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id } });
  if (!a) return { error: "Not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (a.status !== "FAILED") return { error: "This account isn’t in a failed state." };
  await db.hostingAccount.update({ where: { id }, data: { status: "PENDING", error: null } });
  revalidatePath("/dashboard/hosting");
  return { ok: true };
}

