/**
 * The saved admin login(s) for apps installed on this account (WordPress + one-click
 * apps), read from their install-task results for the Overview's App Credentials panel.
 * Ownership-checked and blocked under impersonation, exactly like the SFTP/DB reveals —
 * these are live secrets. Newest install first; a result that isn't a login is skipped.
 */
export async function getHostingAppCredentials(
  accountId: string,
): Promise<{ app: string; url: string; adminUser: string; adminPassword: string; at: string }[]> {
  const user = await requireUser();
  await assertNotImpersonating();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
  if (!a) return [];
  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  const rows = await db.hostingTask.findMany({
    where: { accountId, status: "DONE", kind: { in: ["WORDPRESS_INSTALL", "APP_INSTALL"] }, result: { not: null } },
    orderBy: { createdAt: "desc" },
    take: 12,
  });
  const out: { app: string; url: string; adminUser: string; adminPassword: string; at: string }[] = [];
  for (const t of rows) {
    let p: { adminUser?: string; adminPassword?: string; url?: string; app?: string; name?: string } | null = null;
    try {
      p = JSON.parse(t.result || "");
    } catch {
      p = null;
    }
    if (!p || !p.adminUser || !p.adminPassword) continue;
    out.push({
      app: p.app || p.name || (t.kind === "WORDPRESS_INSTALL" ? "WordPress" : "App"),
      url: p.url || "",
      adminUser: p.adminUser,
      adminPassword: p.adminPassword,
      at: t.createdAt.toISOString(),
    });
  }
  return out;
}

