/**
 * Which website an install / promotion action targets: the account's primary site
 * (`public_html`), or one of its subdomains / addon domains (by row id). Omitting a
 * target defaults to `primary` everywhere, so every existing single-site flow is
 * unchanged.
 */
export type SiteTarget = { kind: "primary" } | { kind: "subdomain"; id: string } | { kind: "addon"; id: string };
/**
 * Validate an install target against an account (cross-tenant guard at the action
 * layer, mirrored again in the worker). For a subdomain/addon the row must exist,
 * belong to THIS account, and be ACTIVE. Returns the JSON `target` to embed in the
 * task payload (undefined for primary → the worker's back-compat default) plus a
 * short, DB-safe suffix that keeps each site's generated database name distinct.
 */
async function validateSiteTarget(
  accountId: string,
  target: SiteTarget | undefined,
): Promise<{ error?: string; payloadTarget?: { kind: string; id: string }; dbSuffix: string }> {
  const kind = target?.kind ?? "primary";
  if (kind === "primary") return { dbSuffix: "" };
  const id = "id" in (target ?? {}) ? String((target as { id: string }).id) : "";
  if (!id) return { error: "Choose a website to install onto.", dbSuffix: "" };
  if (kind === "subdomain") {
    const sub = await db.hostingSubdomain.findFirst({ where: { id, accountId }, select: { status: true } });
    if (!sub) return { error: "That subdomain isn’t part of this account.", dbSuffix: "" };
    if (sub.status !== "ACTIVE") return { error: "That subdomain is still being set up.", dbSuffix: "" };
    return { payloadTarget: { kind: "subdomain", id }, dbSuffix: randomBytes(3).toString("hex") };
  }
  if (kind === "addon") {
    const addon = await db.hostingAddonDomain.findFirst({ where: { id, accountId }, select: { status: true } });
    if (!addon) return { error: "That domain isn’t part of this account.", dbSuffix: "" };
    if (addon.status !== "ACTIVE") return { error: "That domain is still being set up.", dbSuffix: "" };
    return { payloadTarget: { kind: "addon", id }, dbSuffix: randomBytes(3).toString("hex") };
  }
  return { error: "Unknown install target.", dbSuffix: "" };
}
export async function installWordPress(accountId: string, target?: SiteTarget): Promise<HostingResult> {
  const ctx = await ownedActiveAccount(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const { user, a } = ctx;
  if (a._count.databases >= a.maxDatabases) return { error: `WordPress needs a database, but your plan's ${a.maxDatabases} are used. Delete one first.` };
  const tgt = await validateSiteTarget(accountId, target);
  if (tgt.error) return { error: tgt.error };
  // Generate all creds up front; the worker applies them, then the admin login is
  // returned ONCE via the task result. A per-site suffix keeps each site's DB name
  // unique (primary keeps the legacy `<user>_wp` name for back-compat).
  const dbName = `${a.username}_wp${tgt.dbSuffix}`.slice(0, 64);
  const dbUser = dbName.slice(0, 32);
  const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
  const adminPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 18);
  await db.hostingTask.create({
    data: {
      accountId,
      kind: "WORDPRESS_INSTALL",
      payload: JSON.stringify({ dbName, dbUser, dbPassEnc: encryptSecret(dbPass), adminUser: "admin", adminPassEnc: encryptSecret(adminPass), adminEmail: user.email, ...(tgt.payloadTarget ? { target: tgt.payloadTarget } : {}) }),
    },
  });
  revalidatePath("/dashboard/hosting");
  return { ok: true };
}
