/** Install a catalog app (download + DB; the customer finishes the web installer).
 *  An optional `target` installs onto a subdomain/addon docroot instead of the
 *  primary site; omitting it keeps the original primary-only behaviour. */
export async function installApp(accountId: string, slug: string, target?: SiteTarget): Promise<HostingResult> {
  const ctx = await ownedActiveAccount(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const { a } = ctx;
  const app = hostingAppCatalog().find((x) => x.slug === slug);
  if (!app) return { error: "Unknown app." };
  const tgt = await validateSiteTarget(accountId, target);
  if (tgt.error) return { error: tgt.error };
  let payload: Record<string, unknown> = { slug, ...(tgt.payloadTarget ? { target: tgt.payloadTarget } : {}) };
  if (app.needsDb) {
    if (a._count.databases >= a.maxDatabases) return { error: `This app needs a database, but your plan's ${a.maxDatabases} are used.` };
    // Per-site suffix keeps each site's DB name distinct (primary keeps `<user>_<slug>`).
    const dbName = `${a.username}_${slug}${tgt.dbSuffix}`.slice(0, 64);
    const dbUser = dbName.slice(0, 32);
    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
    payload = { ...payload, dbName, dbUser, dbPassEnc: encryptSecret(dbPass) };
  }
  await db.hostingTask.create({ data: { accountId, kind: "APP_INSTALL", payload: JSON.stringify(payload) } });
  revalidatePath("/dashboard/hosting");
  return { ok: true };
}
