/** The higher plans an account may move UP to (never a downgrade): active plans
 *  priced at-or-above and disk at-or-above the current plan, and strictly larger
 *  in at least one, excluding the current plan. Owner or admin. */
export async function listHostingUpgradePlans(accountId: string): Promise<{ currentPlanName?: string; plans?: UpgradePlanView[]; error?: string }> {

 * tx that mutates the account.
 *
 * Billing choice (kept simple + honest): we charge the FULL per-term price
 * DIFFERENCE (new − current) now, and leave the renewal date unchanged; future
 * terms bill at the new plan price. No mid-term proration or refunds — that keeps
 * the flow one debit and never owes the customer money back. The customer sees the
 * exact delta before confirming. Only UP is allowed (a downgrade would need a
 * refund path we don't have).
 */
export async function upgradeHostingPlan(accountId: string, newPlanId: string): Promise<HostingResult> {
  const user = await requireUser();
  await assertNotImpersonating();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
  if (!a) return { error: "Account not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
  const newPlan = await db.hostingPlan.findUnique({ where: { id: newPlanId } });
  if (!newPlan || !newPlan.active) return { error: "That plan isn’t available." };
  if (newPlan.id === a.planId) return { error: "You’re already on this plan." };
  const cur = a.plan;
  // Up-only guard (re-checked server-side; never trust the client's picker).
  if (newPlan.priceCents < cur.priceCents || newPlan.diskGB < cur.diskGB) {
    return { error: "You can only move to a larger plan." };
  }
  const limits = planLimits(newPlan);
  const chargeCents = Math.max(0, newPlan.priceCents - cur.priceCents);
  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };
  try {
    await db.$transaction(async (tx) => {
      if (chargeCents > 0) {
        await debitWallet(tx, user.id, chargeCents);
        await tx.walletTransaction.create({
          data: { userId: user.id, amountCents: -chargeCents, description: `Web Hosting upgrade: ${cur.name} → ${newPlan.name} for ${a.primaryDomain}` },
        });
      }
      // Snapshot the new plan's limits onto the account (same as orderHostingAccount
      // does at creation), so a later plan edit can't silently re-quota this account.
      // phpVersion is left as-is: an upgrade only widens the allowed set.
      await tx.hostingAccount.update({
        where: { id: a.id },
        data: { planId: newPlan.id, diskQuotaMB: limits.diskGB * 1024, maxSites: limits.maxSites, maxDatabases: limits.maxDatabases },
      });
      // Enact the node-level change (raise disk quota + rewrite FPM pool).
      await tx.hostingTask.create({ data: { accountId: a.id, kind: "APPLY_PLAN_LIMITS" } });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
    return { error: "Couldn’t upgrade the plan. Your wallet was not charged — try again." };
  }
  await db.auditLog.create({ data: { userId: user.id, action: "hosting.upgrade", detail: `${cur.name} → ${newPlan.name} · ${a.primaryDomain}` } }).catch(() => {});
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}
export async function createHostingBackup(accountId: string): Promise<HostingResult> {
  const ctx = await ownedActiveAccount(accountId);
