  // Rate-limit: one backup task in flight at a time.
  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "BACKUP", status: { in: ["PENDING", "RUNNING"] } } });
  if (inFlight) return { error: "A backup is already running." };
  await db.hostingTask.create({ data: { accountId, kind: "BACKUP" } });
  revalidatePath("/dashboard/hosting");
  return { ok: true };
}
