/**
 * The money math for a hosting order, in ONE place so the card-split pre-check
 * (`placeHostingOrder`, lib/actions-hosting.ts), the authoritative debit
 * (`orderHostingAccountFor`) and the PayPal/Coinbase order-creation actions
 * (lib/actions-payment-providers.ts) can never diverge on a formula.
 * `fullCharge` is the true total (plan term + storage add-on); `promoCharge` is
 * what a granted first-month-free reduces it to (one PLAN month credited, the
 * add-on never). All the underlying helpers are pure, so call sites only ever
 * differ by the DB reads (annual %, per-GB rate, eligibility) they must each
 * make against the same instant.
 */
export async function hostingChargeCents(
  plan: { priceCents: number },
