  extraGB: number,
): Promise<{ annualPct: number; planTermCents: number; extraTermCents: number; fullCharge: number; promoCharge: number }> {
  const annualPct = await annualDiscountPct();
  const perGbCents = await extraDiskPerGbCents();
  const extraTermCents = extraDiskCentsAt(extraGB, perGbCents) * term;
  const planTermCents = termPriceCents(plan.priceCents, term, annualPct);
  const fullCharge = planTermCents + extraTermCents;
  const promoCharge = Math.max(0, planTermCents - firstMonthCreditCents(planTermCents, term)) + extraTermCents;
  return { annualPct, planTermCents, extraTermCents, fullCharge, promoCharge };
}
