import { notFound } from "next/navigation";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { SiteEditor } from "@/components/customer/site-builder/SiteEditor";
import type { SiteRow } from "@/lib/actions-sites";
import { isSiteDocument, type SiteDocument } from "@/lib/site-render";
export const dynamic = "force-dynamic";
const BASE_DOMAIN = process.env.SITE_BUILDER_BASE_DOMAIN || "nxeon.site";
export default async function SiteEditorPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const user = await requireUser();
  const site = await db.site.findUnique({ where: { id } });
  // Ownership: a customer may only open their own site.
  if (!site || site.userId !== user.id) notFound();
  const draft = await db.siteVersion.findFirst({
    where: { siteId: site.id, isDraft: true },
    orderBy: { createdAt: "desc" },
  });
  const document: SiteDocument | null =
    draft && isSiteDocument(draft.document) ? (draft.document as SiteDocument) : null;
  const row: SiteRow = {
    id: site.id,
    name: site.name,
    slug: site.slug,
    status: site.status,
    templateKey: site.templateKey,
    publishedAt: site.publishedAt ? site.publishedAt.toISOString() : null,
    error: site.error,
    updatedAt: site.updatedAt.toISOString(),
  };
  return <SiteEditor site={row} document={document} baseDomain={BASE_DOMAIN} />;
}
