import { requireUser } from "@/lib/auth";
export const dynamic = "force-dynamic";
export const metadata = { title: "Matrix" };
/**
 * Matrix route — intentionally a thin placeholder.
 *
 * The actual multi-console workspace is rendered by the PERSISTENT MatrixProvider
 * mounted at the portal shell level (components/portal/Shell.tsx →
 * components/customer/claude-code/MatrixProvider.tsx). That provider survives
 * in-portal navigation, so open consoles and their live server terminals are not
 * torn down when the customer moves between pages — which is impossible if the
 * workspace is mounted by this page, because the App Router unmounts a page's
 * subtree on every route change.
 *
 * This page still exists so the route is real (auth-gated, linkable, in the nav);
 * the provider's fixed panel covers this content while the route is active.
 */
export default async function BuildPage() {
  await requireUser();
  // The provider paints the workspace over this region. A short spacer keeps the
  // route from collapsing to zero height before the panel mounts.
  return <div className="min-h-[60vh]" aria-hidden />;
}
